fn parse_int(input: Str) -> Option[Int] {
  if input.len() == 0 { return None(); }
  var result = 0;
  var sign = 1;
  var i = 0;
  if input[0] == '-' { sign = -1; i = 1; }
  while i < input.len() {
    let c = input[i];
    if c < '0' || c > '9' { return None(); }
    result = result * 10 + (c as Int - '0' as Int);
    i = i + 1;
  }
  return Some(sign * result);
}

fn main() -> Int {
  match parse_int("42") {
    Some(v) => return v,
    None => return 0,
  }
}
